import pandas as pd
def daily(df):
    x=df.copy()
    x['wins']=(x['result']=='WIN').astype(int)
    x['decisive']=x['result'].isin(['WIN','LOSS']).astype(int)
    return x.groupby('day')[['wins','decisive']].sum()
